/**
 * Language servers for Settings → LSP: omp's built-in set (resources/omp-lsp-defaults.json,
 * generated by scripts/gen-omp-settings-manifest.mjs) merged with the user's
 * `~/.omp/agent/lsp.json`, the file omp itself reads (it ignores PI_CODING_AGENT_DIR for
 * lsp.json). Whether a server "resolves" is checked on the PATH the agent sidecar gets
 * (inherited PATH + bundled tools). Project-local bins such as `.venv/bin` are only known per
 * project at run time, so a server shown as missing may still work inside a project.
 */
import { accessSync, constants, existsSync, readFileSync, statSync } from "node:fs";
import { homedir } from "node:os";
import { delimiter, isAbsolute, join } from "node:path";
import type { OmpLspListResult, OmpLspSaveInput, OmpLspServer } from "@pi-desktop/shared";
import { writeJsonAtomicSync } from "./atomic-json";
import { appResourcesPath, bundledToolsDir, withBundledTools } from "./omp-binary";

type Raw = Record<string, unknown>;
type Defaults = Record<string, { command: string; fileTypes: string[]; isLinter?: boolean }>;

const strings = (v: unknown): string[] => (Array.isArray(v) ? v.filter((x): x is string => typeof x === "string") : []);

export const userLspPath = () => join(homedir(), ".omp", "agent", "lsp.json");

let defaultsCache: Defaults | undefined;
function readDefaults(): Defaults {
  if (defaultsCache) return defaultsCache;
  try {
    // Written by scripts/gen-omp-settings-manifest.mjs, which owns this shape.
    return (defaultsCache = JSON.parse(readFileSync(join(appResourcesPath(), "omp-lsp-defaults.json"), "utf8")) as Defaults);
  } catch {
    return {}; // not generated yet: list only the user's own servers
  }
}

/** The user's servers plus the other top-level keys to write back. Throws on unreadable JSON. */
function readUser(file: string): { servers: Record<string, Raw>; idleTimeoutMs?: unknown } {
  if (!existsSync(file)) return { servers: {} };
  const raw = JSON.parse(readFileSync(file, "utf8")) as Raw | null;
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) throw new Error("lsp.json must contain a JSON object");
  const { servers, idleTimeoutMs, ...flat } = raw;
  // omp accepts a `servers` wrapper or a flat map, and ignores flat siblings when the wrapper exists.
  const map = (typeof servers === "object" && servers !== null ? servers : flat) as Raw;
  const out: Record<string, Raw> = {};
  for (const [name, cfg] of Object.entries(map)) if (typeof cfg === "object" && cfg !== null) out[name] = cfg as Raw;
  return { servers: out, ...(idleTimeoutMs === undefined ? {} : { idleTimeoutMs }) };
}

/** First match of `command` on `pathVar` (or itself when absolute); null when none is an executable file. */
export function resolveCommand(command: string, pathVar: string, win32 = process.platform === "win32"): string | null {
  const exts = win32 ? ["", ...(process.env.PATHEXT ?? ".EXE;.CMD;.BAT;.COM").split(";")] : [""];
  const dirs = isAbsolute(command) ? [""] : pathVar.split(delimiter).filter(Boolean);
  for (const dir of dirs) {
    for (const ext of exts) {
      const file = dir ? join(dir, command + ext) : command + ext;
      try {
        if (!statSync(file).isFile()) continue;
        accessSync(file, constants.X_OK);
        return file;
      } catch {
        // not here
      }
    }
  }
  return null;
}

export function listLspServers(
  file = userLspPath(),
  toolsDir = bundledToolsDir(),
  env = withBundledTools(process.env, toolsDir),
): OmpLspListResult {
  const defaults = readDefaults();
  let user: Record<string, Raw> = {};
  let error: string | undefined;
  try {
    user = readUser(file).servers;
  } catch (err) {
    error = err instanceof Error ? err.message : String(err);
  }
  const pathVar = env.PATH ?? env.Path ?? "";
  const servers: OmpLspServer[] = [];
  for (const name of new Set([...Object.keys(defaults), ...Object.keys(user)])) {
    const base = defaults[name];
    const merged: Raw = { ...base, ...user[name] };
    if (typeof merged.command !== "string" || !merged.command) continue;
    const resolved = resolveCommand(merged.command, pathVar);
    servers.push({
      name,
      command: merged.command,
      fileTypes: strings(merged.fileTypes),
      builtin: base !== undefined,
      custom: user[name] !== undefined,
      disabled: merged.disabled === true,
      isLinter: merged.isLinter === true,
      resolved,
      bundled: !!resolved && !!toolsDir && resolved.startsWith(toolsDir),
    });
  }
  servers.sort(
    (a, b) =>
      Number(b.custom) - Number(a.custom) ||
      Number(!!b.resolved) - Number(!!a.resolved) ||
      a.name.localeCompare(b.name),
  );
  return { servers, configPath: file, ...(error ? { error } : {}) };
}

const NAME = /^[A-Za-z0-9._-]{1,64}$/;

/** Merge `input` into the server's lsp.json entry. A name omp does not ship needs `command` and `fileTypes`. */
export function saveLspServer(input: OmpLspSaveInput, file = userLspPath()): { ok: boolean; error?: string } {
  const name = input.name.trim();
  if (!NAME.test(name)) return { ok: false, error: "name: letters, digits, . _ - only (max 64)" };
  try {
    const cur = readUser(file);
    const patch: Raw = {};
    const command = input.command?.trim();
    if (command) patch.command = command;
    if (input.args) patch.args = input.args;
    if (input.fileTypes) patch.fileTypes = input.fileTypes.map((t) => (t.startsWith(".") ? t : `.${t}`));
    if (input.rootMarkers) patch.rootMarkers = input.rootMarkers;
    if (input.disabled !== undefined) patch.disabled = input.disabled;
    const entry: Raw = { ...cur.servers[name], ...patch };
    if (!(name in readDefaults())) {
      if (typeof entry.command !== "string" || !entry.command) return { ok: false, error: "command is required" };
      if (strings(entry.fileTypes).length === 0) return { ok: false, error: "at least one file type is required" };
      // omp requires rootMarkers on a new server; "." matches any project.
      if (strings(entry.rootMarkers).length === 0) entry.rootMarkers = ["."];
    }
    writeJsonAtomicSync(file, { servers: { ...cur.servers, [name]: entry }, ...(cur.idleTimeoutMs === undefined ? {} : { idleTimeoutMs: cur.idleTimeoutMs }) });
    return { ok: true };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : String(err) };
  }
}

export function removeLspServer(name: string, file = userLspPath()): { ok: boolean; error?: string } {
  try {
    const cur = readUser(file);
    if (!(name in cur.servers)) return { ok: true };
    const { [name]: _gone, ...servers } = cur.servers;
    writeJsonAtomicSync(file, { servers, ...(cur.idleTimeoutMs === undefined ? {} : { idleTimeoutMs: cur.idleTimeoutMs }) });
    return { ok: true };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : String(err) };
  }
}
